Hmmm yeah I think you need to modify this in MOG's plugin (I changed the drawItemName line to push the y lower depending on the index). I'm not 100% sure if you should draw the whole itemRect or whatever lower though. But try and test with this:
Window_EquipSlot.prototype.drawItem = function(index) {
this.contents.fontSize = Moghunter.scEquip_FontSize;
if (this._actor) {
var rect = this.itemRectForText(index);
this.changeTextColor(this.systemColor());
this.changePaintOpacity(this.isEnabled(index));
this.drawItemName(this._actor.equips()[index], rect.x + 138, rect.y+index*5); // CHANGED THIS
this.changePaintOpacity(true);
}
};
EDIT: Change 5 to another number to fit your game.

